// Nome do node: "Organizar Chaves API"

// Pega todas as chaves retornadas
const chaves = $input.all();

// Organiza por plataforma (busca, não assume ordem!)
const chaveML = chaves.find(c => c.json.plataforma === 'mercadolivre')?.json || null;
const chaveAmazon = chaves.find(c => c.json.plataforma === 'amazon')?.json || null;
const chaveShopee = chaves.find(c => c.json.plataforma === 'shopee')?.json || null;
const chaveResgateShopee = chaves.find(c => c.json.plataforma === 'resgate-shopee')?.json || null;

// Retorna SEMPRE nessa estrutura (ordem garantida)
return {
  mercadolivre: chaveML ? {
    id: chaveML.id,
    etiqueta: chaveML.etiqueta,
    ssid_encrypted: chaveML.ssid_encrypted,
    csrf_token: chaveML.csrf_token
  } : null,

  amazon: chaveAmazon ? {
    id: chaveAmazon.id,
    access_key: chaveAmazon.access_key,
    secret_key: chaveAmazon.secret_key,
    partner_tag: chaveAmazon.partner_tag
  } : null,

  shopee: chaveShopee ? {
    id: chaveShopee.id,
    affiliate_id: chaveShopee.shopee_affiliate_id,
    app_key: chaveShopee.shopee_app_key
  } : null,

  resgate_shopee: chaveResgateShopee ? {
    id: chaveResgateShopee.id,
    link: chaveResgateShopee.link
  } : null
};

// Pega output do AI Agent (pode vir em diferentes formatos)
let rawOutput = $input.item.json.output || $input.item.json;
if (Array.isArray(rawOutput)) {
  rawOutput = rawOutput[0].output || rawOutput[0];
}

// Remove markdown em volta do JSON
let output = rawOutput.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

// Parse do JSON do modelo — usado APENAS para "link" e "tem_cupom_resgate".
// O TEXTO da mensagem NÃO vem mais do modelo (ver abaixo).
let dados;
try {
  dados = JSON.parse(output);
} catch (e) {
  try {
    let outputEscaped = output.replace(/\\n/g, '\\\\n');
    dados = JSON.parse(outputEscaped);
  } catch (e2) {
    throw new Error(`Erro ao parsear resposta do AI Agent: ${e2.message}`);
  }
}
if (!dados || typeof dados !== 'object') {
  throw new Error('Resposta do AI Agent não é um objeto válido');
}

// ─────────────────────────────────────────────────────────────────────────
// LIMPEZA DETERMINÍSTICA A PARTIR DO TEXTO ORIGINAL (não usa o texto do LLM)
//
// Mantém EMOJIS e ESPAÇAMENTO exatamente como no original. O código só
// REMOVE: símbolos de markdown (* ~ _itálico_), linhas com link, rótulos de
// CTA sozinhos e linhas de streaming/assinatura. NUNCA reescreve, NUNCA
// duplica e NUNCA mexe em preços/cupons. O link de afiliado é adicionado
// depois, pelos nodes "Preparar Mensagem Final".
// ─────────────────────────────────────────────────────────────────────────
function limparTexto(txt) {
  if (!txt || typeof txt !== 'string') return '';

  const temLink = /https?:\/\//i;

  // Linha que é SÓ um rótulo de CTA (sem mais nada útil)
  const ehRotuloCTA = /^\s*[^\w]*\s*(compre aqui|compre em|comprar aqui|link do produto|link da oferta|link aqui|link|pegar oferta|garanta o seu|garanta|clique aqui|acesse aqui|acesse)\s*:?\s*$/i;

  // Linha de streaming/assinatura digital (termos específicos p/ não pegar produto)
  const ehStreaming = /(prime video|amazon prime|seja prime|assine (?:o )?prime|teste prime|kindle unlimited|spotify|netflix|disney\s*\+|paramount\s*\+|star\s*\+|apple tv\s*\+|hbo max|globoplay|youtube premium|deezer|30 dias gr[aá]tis|assine agora|assine aqui|assine e ganhe|assinatura gr[aá]tis|experimente gr[aá]tis|per[ií]odo de teste|aproveite ainda mais benef)/i;

  const linhas = [];
  for (let linha of txt.split('\n')) {
    // Remove SÓ os marcadores de formatação (mantém emojis intactos):
    linha = linha.replace(/[*~]/g, '');                         // *negrito* / ~riscado~
    linha = linha.replace(/(^|\s)_([^_\n]+)_(?=\s|$)/g, '$1$2'); // _itálico_ (não toca em cupom tipo ABC_DEF)
    linha = linha.replace(/[ \t]+$/g, '');                      // espaço/tab no fim

    if (temLink.test(linha)) continue;       // qualquer linha com URL
    if (ehRotuloCTA.test(linha)) continue;   // rótulo de CTA isolado
    if (ehStreaming.test(linha)) continue;   // streaming/assinatura

    linhas.push(linha);
  }

  // Preserva o espaçamento do original; só evita buracos gigantes (3+ vazias -> 2)
  return linhas.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

// Texto SEMPRE vem do original (Webhook), nunca do modelo
const textoOriginal = $item(0).$node["Webhook"].json["body"]["text"] || "";
dados.texto_formatado = limparTexto(textoOriginal);

return [{ json: dados }];

// Pega o link do nó anterior
const link = $item("0").$node["DESENCURTADOR_DE_LINK1"].json["url_final"];

// FIX-GUARD-NULL-LINK-START
if (!link || typeof link !== "string") {
  return [{json: {plataforma: null, link: null, sem_link: true}}];
}
// FIX-GUARD-NULL-LINK-END


// Identifica a plataforma baseada na URL
let plataforma = "outra";
if (link.includes("shopee.com") || link.includes("s.shopee")) {
  plataforma = "shopee";
} else if (link.includes("mercadolivre.com") || link.includes("mercadolibre.com")) {
  plataforma = "mercadolivre";
} else if (link.includes("amzn.to") || link.includes("amazon.com")) {
  plataforma = "amazon";
}

// Retorna o resultado no formato padrão
return {
  plataforma: plataforma,
  link_original: link
};

// Monta o header de autorização
const authHeader = `SHA256 Credential=${$input.item.json.appId}, Timestamp=${$input.item.json.timestamp}, Signature=${$input.item.json.signature}`;

return {
  payload: $input.item.json.payload,
  authHeader: authHeader
};

// Pegar link desencurtado do nó anterior
const link = $item(0).$node["DESENCURTADOR_DE_LINK1"].json["url_final"];

// GUARD 1: link vazio/null
if (!link || typeof link !== "string") {
  return [{ json: { skip: true, reason: "link_vazio_ou_null", link: link || "" } }];
}

// GUARD 2: link ainda curto (desencurtador falhou)
if (link.includes("s.shopee.com.br") || link.includes("shp.ee") || link.includes("shope.ee")) {
  return [{ json: { skip: true, reason: "desencurtador_nao_funcionou", link } }];
}

// 3 patterns pra extrair shop_id e item_id em formatos diferentes
const patterns = [
  /-i\.(\d+)\.(\d+)/,              // formato clássico: produto-nome-i.SHOPID.ITEMID
  /shopee\.com\.br\/[^\/?]+\/(\d+)\/(\d+)/, // storefront: /opaanlp/SHOPID/ITEMID
  /shopId=(\d+).*?itemId=(\d+)/i,    // query: ?shopId=X&itemId=Y
];

let shopId = null, itemId = null;
for (const p of patterns) {
  const m = link.match(p);
  if (m) { shopId = m[1]; itemId = m[2]; break; }
}

// GUARD 3: nenhum padrão bateu
if (!shopId || !itemId) {
  return [{ json: { skip: true, reason: "nao_eh_url_de_produto_shopee", link } }];
}

return [{
  json: {
    shopId: shopId,
    itemId: itemId,
    link: link,
    link_completo: link
  }
}];

// Pegar o link de entrada
const inputLink = $input.item.json.link || $input.item.json.body?.link || "";

// 6 patterns pra capturar ASIN em formatos diferentes
const patterns = [
  /\/dp\/([A-Z0-9]{10})/i,
  /\/gp\/product\/([A-Z0-9]{10})/i,
  /\/gp\/aw\/d\/([A-Z0-9]{10})/i,
  /\/product\/([A-Z0-9]{10})/i,
  /[?&]asin=([A-Z0-9]{10})/i,
  /\/([A-Z0-9]{10})(?:[?\/]|$)/i,
];

let asin = null;
for (const p of patterns) {
  const m = inputLink.match(p);
  if (m) { asin = m[1].toUpperCase(); break; }
}

// SOFT FAIL — não derruba execução
if (!asin) {
  return {
    json: {
      asin: null,
      originalLink: inputLink,
      asin_fail: true,
      reason: "no_asin_pattern_match"
    }
  };
}

return { json: { asin: asin, originalLink: inputLink } };

// Pega dados dos nós anteriores
const instancia = $item("0").$node["DADOS_USUARIO"].json["instance_name"];
const textoFormatado = $item("0").$node["Code in JavaScript3"].json["texto_formatado"];
const linkCurto = $item("0").$node["HTTP Request9"].json["link_curto"];

// Cria caption com CTA
const novoCaptionCompleto = `${textoFormatado}\n\nCompre aqui: ${linkCurto}`;

console.log('Link curto:', linkCurto);
console.log('Caption final:', novoCaptionCompleto);

return [{
  json: {
    instancia: instancia,
    caption: novoCaptionCompleto,
    link_curto: linkCurto
  }
}];

// Detectar skip upstream antes de qualquer coisa
const upstream = $item(0).$node["Code in JavaScript4"]?.json;
if (upstream?.skip === true) {
  return { json: { skip: true, reason: upstream.reason, link: upstream.link || "" } };
}

const appId = $item(0).$node["DADOS_USUARIO"].json["shopee_affiliate_id"];
const secret = $item(0).$node["DADOS_USUARIO"].json["shopee_chave_id"];

// Resolver link: primeiro Code in JavaScript4, fallback AI Agent1 (com check seguro)
let link = upstream?.link_completo;

if (!link) {
  // Tentar AI Agent1 só se o node tem dados disponíveis
  try {
    // Acessar $node sem cair em "node hasn't been executed"
    const allNodes = Object.keys($items || {});
    let aiOutput = null;
    try {
      aiOutput = $item(0).$node["AI Agent1"]?.json?.output || $item(0).$node["AI Agent1"]?.json?.text;
    } catch (innerErr) {
      // AI Agent1 não foi executado nesse caminho — ok, segue
      aiOutput = null;
    }
    if (aiOutput) {
      const cleaned = aiOutput.replace(/```json\n?/g, "").replace(/```\n?/g, "").trim();
      const aiData = JSON.parse(cleaned);
      link = aiData.link_completo;
    }
  } catch (e) {
    console.log("AI Agent1 fallback falhou:", e.message);
  }
}

if (!link) {
  return { json: { skip: true, reason: "sem_link_para_encurtar", link: "" } };
}

// Validar credenciais Shopee
if (!appId || !secret) {
  return { json: { skip: true, reason: "credenciais_shopee_ausentes" } };
}

const timestamp = Math.floor(Date.now() / 1000);
const payload = JSON.stringify({
  query: `mutation { generateShortLink(input: { originUrl: \"${link}\" }) { shortLink } }`
});
const stringToSign = `${appId}${timestamp}${payload}${secret}`;

return {
  json: {
    link: link,
    payload: payload,
    appId: appId,
    timestamp: timestamp,
    stringToSign: stringToSign
  }
};

