// Pega output do Gemini
let output = $input.item.json.output || $input.item.json.text;

// Remove markdown se houver
output = output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

// Parse do JSON
let dados;
try {
  dados = JSON.parse(output);
} catch (e) {
  console.error('Erro ao parsear JSON do Gemini:', e);
  console.error('Output recebido:', output);
  throw new Error('Gemini retornou formato inválido');
}

// Retorna no formato esperado
return [{
  json: {
    shop_id: dados.shop_id,
    item_id: dados.item_id,
    link_completo: dados.link_completo
  }
}];

// Pega URL do upload anterior
const imageUrl = $input.item.json.url;
const codigo = $input.item.json.codigo;
const tamanho = $input.item.json.tamanho_bytes;

console.log('✅ Imagem disponível em:', imageUrl);
console.log('📦 Tamanho:', tamanho, 'bytes');
console.log('🗑️ Será deletada automaticamente em 30 minutos');

return {
  json: {
    imagem_url: imageUrl,
    codigo: codigo,
    tamanho_bytes: tamanho
  }
};

// Pega link curto do Encurtar Link API
const encurtarOut = $item(0).$node["Encurtar Link API"]?.json;
const linkCurto = encurtarOut?.data?.generateShortLink?.shortLink;

if (!linkCurto) {
  // SEM LINK = ABORTA (não mandar mensagem incompleta)
  const errCode = encurtarOut?.errors?.[0]?.extensions?.code || "unknown";
  throw new Error(`Shopee createLink falhou (${errCode}) — abortando para não enviar caption sem link`);
}

const descricaoSemLink = $item(0).$node["Code in JavaScript3"]?.json?.texto_formatado || "";
let textoCompleto = `${descricaoSemLink}\n\nCompre aqui: ${linkCurto}`;

// ─────────────────────────────────────────────────────────────────────────
// FIX (cupom Shopee) — adiciona o link de resgate do cliente de forma
// determinística. Antes isso dependia do LLM manter a linha do cupom no
// texto_formatado, o que falhava na maioria das ofertas (link de resgate
// não era enviado). O link vem da credencial "resgate-shopee" do usuário
// (DADOS_USUARIO). Detecta cupom pela flag do AI OU por detecção no texto.
// ─────────────────────────────────────────────────────────────────────────
const textoOriginal = ($item(0).$node["Webhook"]?.json?.body?.text || "").toLowerCase();
const cupomPorTexto = /(resgate (?:o |seu )?cupom|resgatar cupom|cupom aqui)/i.test(textoOriginal);
const cupomPorFlag = $item(0).$node["Code in JavaScript3"]?.json?.tem_cupom_resgate === true;
const linkResgate = $item(0).$node["DADOS_USUARIO"]?.json?.["resgate-shopee"];

if ((cupomPorFlag || cupomPorTexto) && linkResgate) {
  textoCompleto += `\n\n🎟️ Resgate o cupom aqui: ${linkResgate}`;
}

return [{ json: { texto: textoCompleto, link_curto: linkCurto } }];

// Nome do node: "Preparar Mensagem Final6" (ML)
// FIX 09/06: throw quando GERAR LINK falha (401/404) pra nao mandar "Compre aqui: undefined"

const instancia = $item("0").$node["DADOS_USUARIO"].json["instance_name"];
const textoFormatado = $item("0").$node["Code in JavaScript3"].json["texto_formatado"];

// Aceitar link de GERAR LINK ou GERAR LINK1 (fallback sem /p/)
let linkNovo = '';
try {
  linkNovo = $item("0").$node["GERAR LINK"].json["short_url"];
} catch (e) {}
if (!linkNovo) {
  try {
    linkNovo = $item("0").$node["GERAR LINK1"].json["short_url"];
  } catch (e) {}
}

// GUARD: se nao tem link, ABORTA — nao manda "Compre aqui: undefined"
if (!linkNovo) {
  const erro = $item("0").$node["GERAR LINK"]?.json?.error || $item("0").$node["GERAR LINK"]?.json?.status || "sem short_url";
  throw new Error(`ML createLink falhou (${erro}) — abortando para nao enviar caption sem link`);
}

// Construir a mensagem final
const mensagemFinal = `${textoFormatado}\n\nCompre aqui: ${linkNovo}`;

return [
  {
    instancia: instancia,
    mensagem: mensagemFinal,
    link: linkNovo
  }
];

const items = $input.all();

return items.map(item => {
  const urlFinal = $item("0").$node["DESENCURTADOR_DE_LINK1"].json["url_final"];
  const match = urlFinal.match(/^(https?:\/\/[^\/]+\/[^\?]+)/);
  const urlLimpa = match ? match[1] + "?tag=" : urlFinal;

  return {
    json: {
      ...item.json,
      url_limpa: urlLimpa
    }
  };
});

const linkFinal = $input.item.json["link-final-amazon"] || "";

const match = linkFinal.match(/[?&]tag=([^&]*)/);
const tag = match ? match[1].trim() : "";

if (!tag) {
  // SOFT FAIL — cliente sem credencial Amazon (tag vazia ou ausente)
  return {
    json: {
      ...($input.item.json),
      "link-final-amazon": linkFinal,
      skip: true,
      reason: "cliente_sem_tag_amazon"
    }
  };
}

return {
  json: {
    ...($input.item.json),
    "link-final-amazon": linkFinal,
    tag_validada: tag
  }
};

// N8N Code Node - Verificador Título vs Descrição
const descricao = $item(0).$node["Preparar Mensagem Final6"].json["mensagem"] || '';
const titulo = $item(0).$node["confere titulo e desc"].json["titulo"] || '';

// FIX 09/06: se og-image-api não devolve título (rota /api/og-title não existe),
// não temos como validar. Considera 'sucesso' pra não bloquear envio de ML.
if (!titulo || titulo.trim().length === 0) {
  return [{ json: { status: 'sucesso', motivo: 'titulo vazio — bypass do quality control' } }];
}

function normalizar(texto) {
  return texto
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(p => p.length > 2);
}

const stopWords = [
  'para', 'com', 'por', 'que', 'uma', 'uns', 'das',
  'dos', 'seu', 'sua', 'aqui', 'esse', 'essa', 'kit',
  'pro', 'pre', 'novo', 'nova', 'original', 'oficial',
  'loja', 'link', 'oferta', 'preco', 'frete', 'gratis',
  'cupom', 'desconto', 'promocao', 'compre', 'corre',
  'baixou', 'cada', 'dia', 'semana', 'confira', 'aproveite',
  'garantia', 'produto', 'melhor', 'super', 'mega', 'otima',
  'avaliacao', 'estrelas', 'vendidos', 'unidades'
];

const palavrasDesc = normalizar(descricao).filter(p => !stopWords.includes(p));
const palavrasTitulo = normalizar(titulo).filter(p => !stopWords.includes(p));

if (palavrasTitulo.length === 0) {
  return [{ json: { status: 'sucesso', motivo: 'titulo so com stopwords — bypass' } }];
}

const matches = palavrasTitulo.filter(pt =>
  palavrasDesc.some(pd => pd.includes(pt) || pt.includes(pd))
);
const score = matches.length / palavrasTitulo.length;

const resultado = score >= 0.35
  ? { status: 'sucesso', motivo: 'descrição compatível com o produto' }
  : { status: 'erro', motivo: 'produto não corresponde ao título' };

return [{ json: resultado }];

// N8N Code Node - Extrator de Link de Compra
const texto = $item(0).$node["Webhook"].json["body"]["text"] || '';
const linhas = texto.split('\n');

const palavrasCupom = ['cupom', 'resgate', 'cole aqui', 'cole o cupom', 'copie', 'desconto aqui', 'aplique', 'resgate o cupom', 'resgate seu cupom'];
const palavrasCompra = ['link da oferta', 'compre aqui', 'confira', 'corre', 'aproveite', 'garanta', 'acesse', 'clique', 'link aqui', 'oferta', 'compre'];

let linkCompra = null;
let linkCupom = null;

for (let i = 0; i < linhas.length; i++) {
  const linha = linhas[i].trim();
  const urls = linha.match(/https?:\/\/[^\s\]>)]+/g);
  if (!urls) continue;

  const url = urls[0];
  const anterior = (linhas[i - 1] || '').toLowerCase();
  const linhaLower = linha.toLowerCase();

  const contextoCupom = palavrasCupom.some(p =>
    anterior.includes(p) || linhaLower.includes(p)
  );

  if (contextoCupom) {
    linkCupom = url;
  } else if (!linkCompra) {
    linkCompra = url;
  }
}

// Se só achou um link e caiu como cupom, provavelmente é de compra
if (!linkCompra && linkCupom) {
  linkCompra = linkCupom;
  linkCupom = null;
}

// Retorna só o link de compra (igual o Gemini retornava: só a URL crua)
if (!linkCompra) {
  return [{ json: { erro: 'nenhum link de compra encontrado' } }];
}

return [{ json: { link_compra: linkCompra } }];
